def validation_metrics(
    accum: dict[str, list[np.ndarray]],
    loss_totals: dict[str, float],
    item_count: int,
) -> dict[str, Any]:
    graph_logits = np.concatenate(accum["attack_logits"])
    graph_scores = 1.0 / (1.0 + np.exp(-graph_logits))
    graph_targets = np.concatenate(accum["graph_targets"]).astype(
        np.int64
    )
    active_mask = graph_targets == 1

    graph = binary_metrics(graph_scores, graph_targets)
    graph["auroc"] = binary_auroc(
        graph_scores,
        graph_targets,
    )
    graph["average_precision"] = binary_average_precision(
        graph_scores,
        graph_targets,
    )

    count_logits = np.concatenate(accum["count_logits"])
    count_targets = np.concatenate(accum["count_targets"]).astype(
        np.int64
    )
    active_count_logits = count_logits[active_mask]
    active_count_targets = count_targets[active_mask]
    count_predictions = (
        np.argmax(active_count_logits, axis=1) + 1
    )
    count_accuracy = float(
        np.mean(count_predictions == active_count_targets)
    )
    count_macro_f1 = multiclass_macro_f1(
        count_predictions,
        active_count_targets,
        COUNT_CLASS_VALUES,
    )

    roles = {}
    for role in ("source", "transit", "victim", "path"):
        logits = np.concatenate(accum[f"{role}_logits"])
        scores = 1.0 / (1.0 + np.exp(-logits))
        targets = np.concatenate(
            accum[f"{role}_targets"]
        ).astype(np.int64)
        flattened = binary_metrics(
            scores.reshape(-1),
            targets.reshape(-1),
        )
        flattened["auroc"] = binary_auroc(
            scores.reshape(-1),
            targets.reshape(-1),
        )
        flattened["average_precision"] = (
            binary_average_precision(
                scores.reshape(-1),
                targets.reshape(-1),
            )
        )
        flattened.update(
            exact_multilabel(
                scores,
                targets,
                active_mask,
            )
        )
        roles[role] = flattened

    components = [
        graph["auroc"],
        graph["average_precision"],
        count_macro_f1,
        roles["source"]["average_precision"],
        roles["transit"]["average_precision"],
        roles["victim"]["average_precision"],
        roles["path"]["average_precision"],
    ]
    if not all(math.isfinite(value) for value in components):
        raise RuntimeError(
            f"non-finite validation selection component: "
            f"{components}"
        )
    selection_score = float(np.mean(components))

    return {
        "loss": {
            key: value / item_count
            for key, value in loss_totals.items()
        },
        "selection_score": selection_score,
        "selection_components": {
            "graph_auroc": graph["auroc"],
            "graph_average_precision": (
                graph["average_precision"]
            ),
            "count_active_macro_f1": count_macro_f1,
            "source_average_precision": (
                roles["source"]["average_precision"]
            ),
            "transit_average_precision": (
                roles["transit"]["average_precision"]
            ),
            "victim_average_precision": (
                roles["victim"]["average_precision"]
            ),
            "path_average_precision": (
                roles["path"]["average_precision"]
            ),
        },
        "graph": graph,
        "count_active": {
            "accuracy": count_accuracy,
            "macro_f1": count_macro_f1,
            "items": int(active_mask.sum()),
        },
        "roles": roles,
        "threshold_policy": {
            "reporting_threshold": 0.5,
            "threshold_tuning_performed": False,
            "selection_metrics_are_threshold_free_except_count_macro_f1": True,
        },
    }

def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()

def exact_multilabel(
    scores: np.ndarray,
    targets: np.ndarray,
    active_mask: np.ndarray,
    threshold: float = 0.5,
) -> dict[str, float]:
    scores = np.asarray(scores, dtype=np.float64)
    targets = np.asarray(targets, dtype=np.int64)
    predictions = (scores >= threshold).astype(np.int64)
    all_exact = float(
        np.mean(np.all(predictions == targets, axis=1))
    )
    if np.any(active_mask):
        active_exact = float(
            np.mean(
                np.all(
                    predictions[active_mask]
                    == targets[active_mask],
                    axis=1,
                )
            )
        )
    else:
        active_exact = float("nan")
    return {
        "exact_all": all_exact,
        "exact_active": active_exact,
    }

def compute_losses(
    outputs: dict[str, torch.Tensor],
    batch: dict[str, torch.Tensor],
    graph_pos_weight: torch.Tensor,
    role_pos_weights: dict[str, torch.Tensor],
) -> dict[str, torch.Tensor]:
    active = batch["graph"] > 0.5
    if not bool(active.any()):
        count_loss = outputs["count_logits"].sum() * 0.0
    else:
        active_targets = batch["count"][active] - 1
        if not bool(
            ((active_targets >= 0) & (active_targets <= 3)).all()
        ):
            raise RuntimeError(
                "active Count4 targets are outside 0..3"
            )
        count_loss = F.cross_entropy(
            outputs["count_logits"][active],
            active_targets,
        )

    losses = {
        "graph": F.binary_cross_entropy_with_logits(
            outputs["attack_logits"],
            batch["graph"],
            pos_weight=graph_pos_weight,
        ),
        "count": count_loss,
        "source": F.binary_cross_entropy_with_logits(
            outputs["source_logits"],
            batch["source"],
            pos_weight=role_pos_weights["source"],
        ),
        "transit": F.binary_cross_entropy_with_logits(
            outputs["transit_logits"],
            batch["transit"],
            pos_weight=role_pos_weights["transit"],
        ),
        "victim": F.binary_cross_entropy_with_logits(
            outputs["victim_logits"],
            batch["victim"],
            pos_weight=role_pos_weights["victim"],
        ),
        "path": F.binary_cross_entropy_with_logits(
            outputs["path_logits"],
            batch["path"],
            pos_weight=role_pos_weights["path"],
        ),
    }
    losses["total"] = sum(losses.values())
    if not all(torch.isfinite(value) for value in losses.values()):
        raise RuntimeError("non-finite multitask loss")
    return losses

def binary_average_precision(
    scores: np.ndarray,
    targets: np.ndarray,
) -> float:
    scores = np.asarray(scores, dtype=np.float64).reshape(-1)
    targets = np.asarray(targets, dtype=np.int64).reshape(-1)
    positive_count = int((targets == 1).sum())
    if positive_count == 0:
        return float("nan")
    order = np.argsort(-scores, kind="mergesort")
    ordered_targets = targets[order]
    cumulative_positive = np.cumsum(ordered_targets == 1)
    positions = np.arange(1, len(targets) + 1)
    precision_at_k = cumulative_positive / positions
    return float(
        precision_at_k[ordered_targets == 1].sum()
        / positive_count
    )

def binary_auroc(
    scores: np.ndarray,
    targets: np.ndarray,
) -> float:
    scores = np.asarray(scores, dtype=np.float64).reshape(-1)
    targets = np.asarray(targets, dtype=np.int64).reshape(-1)
    positive = targets == 1
    negative = targets == 0
    n_positive = int(positive.sum())
    n_negative = int(negative.sum())
    if n_positive == 0 or n_negative == 0:
        return float("nan")
    ranks = average_ranks(scores)
    rank_sum_positive = float(ranks[positive].sum())
    return (
        rank_sum_positive
        - n_positive * (n_positive + 1) / 2.0
    ) / (n_positive * n_negative)

def average_ranks(values: np.ndarray) -> np.ndarray:
    order = np.argsort(values, kind="mergesort")
    sorted_values = values[order]
    ranks = np.empty(len(values), dtype=np.float64)
    start = 0
    while start < len(values):
        end = start + 1
        while (
            end < len(values)
            and sorted_values[end] == sorted_values[start]
        ):
            end += 1
        average_rank = (start + 1 + end) / 2.0
        ranks[order[start:end]] = average_rank
        start = end
    return ranks

def main() -> int:
    args = parse_args()

    repo = Path(args.repo).expanduser().resolve()
    output_dir = Path(
        args.output_dir
    ).expanduser().resolve()
    installed_script = Path(
        args.installed_script
    ).expanduser().resolve()
    output_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    working_dir = output_dir / "A1_WORKING"
    working_dir.mkdir(
        parents=True,
        exist_ok=True,
    )
    contract_path = output_dir / (
        "V5_P3_D4_A1_RESUMABLE_EXECUTION_CONTRACT.json"
    )
    schema_path = output_dir / (
        "V5_P3_D4_A1_DECODED_OUTPUT_SCHEMA.json"
    )
    final_outputs_path = output_dir / (
        "V5_P3_D4_A1_EXACT_VALIDATION_OUTPUTS.npz"
    )
    report_path = output_dir / f"{STAGE}_REPORT.json"
    lock_path = output_dir / f"{STAGE}_LOCK.json"
    complete_path = output_dir / f"{STAGE}_COMPLETE"
    failure_path = output_dir / f"{STAGE}_FAILURE.json"

    d3_dir = (
        repo
        / "reports/v5/p3_d3_resumable_a1_exact_decoder_chunk_preflight"
    )
    d3_report_path = d3_dir / (
        "V5_P3_D3_RESUMABLE_A1_EXACT_"
        "DECODER_CHUNK_PREFLIGHT_REPORT.json"
    )
    d3_lock_path = d3_dir / (
        "V5_P3_D3_RESUMABLE_A1_EXACT_"
        "DECODER_CHUNK_PREFLIGHT_LOCK.json"
    )
    d2_dir = (
        repo
        / "reports/v5/p3_d2_raw_and_frozen_a0_validation_evaluation"
    )
    d2_report_path = d2_dir / (
        "V5_P3_D2_RAW_AND_FROZEN_A0_"
        "TRANCHE_A_VALIDATION_EVALUATION_REPORT.json"
    )
    d2_lock_path = d2_dir / (
        "V5_P3_D2_RAW_AND_FROZEN_A0_"
        "TRANCHE_A_VALIDATION_EVALUATION_LOCK.json"
    )
    d1_dir = (
        repo
        / "reports/v5/p3_d1_immutable_validation_logit_export"
    )
    d1_export_path = d1_dir / (
        "V5_P3_D1_TRANCHE_A_VALIDATION_LOGITS_AND_LABELS.npz"
    )
    d1_lock_path = d1_dir / (
        "V5_P3_D1_IMMUTABLE_TRANCHE_A_"
        "VALIDATION_LOGIT_EXPORT_LOCK.json"
    )
    decoder_path = (
        repo
        / "src/decoders/v5_legal_xy_exact_decoder_certified.py"
    )
    preserved_decoder_path = (
        repo
        / "reports/v5/p2_canonical_preservation/decoder/"
        "v5_legal_xy_exact_decoder_certified.py"
    )

    required = [
        d3_report_path,
        d3_lock_path,
        d2_report_path,
        d2_lock_path,
        d1_export_path,
        d1_lock_path,
        decoder_path,
        preserved_decoder_path,
    ]
    missing = [
        str(path)
        for path in required
        if not path.is_file()
    ]
    if missing:
        raise RuntimeError(
            f"required artifacts missing: {missing}"
        )

    d3_report = json.loads(
        d3_report_path.read_text(
            encoding="utf-8"
        )
    )
    d3_lock = json.loads(
        d3_lock_path.read_text(
            encoding="utf-8"
        )
    )
    d2_report = json.loads(
        d2_report_path.read_text(
            encoding="utf-8"
        )
    )
    d2_lock = json.loads(
        d2_lock_path.read_text(
            encoding="utf-8"
        )
    )
    d1_lock = json.loads(
        d1_lock_path.read_text(
            encoding="utf-8"
        )
    )

    if d3_report.get("status") != "PASS":
        raise RuntimeError("D3 report is not PASS")
    if not d3_report.get(
        "decision",
        {},
    ).get(
        "A1_exact_full_validation_evaluation_authorized"
    ):
        raise RuntimeError(
            "D3 did not authorize full A1 validation"
        )
    if d3_lock.get(
        "report_sha256"
    ) != sha256_file(d3_report_path):
        raise RuntimeError(
            "D3 report/lock SHA mismatch"
        )
    if d2_lock.get(
        "report_sha256"
    ) != sha256_file(d2_report_path):
        raise RuntimeError(
            "D2 report/lock SHA mismatch"
        )
    export_sha = sha256_file(
        d1_export_path
    )
    if d1_lock.get(
        "export_sha256"
    ) != export_sha:
        raise RuntimeError(
            "D1 export SHA mismatch"
        )

    decoder_sha = sha256_file(
        decoder_path
    )
    preserved_sha = sha256_file(
        preserved_decoder_path
    )
    if decoder_sha != preserved_sha:
        raise RuntimeError(
            "working decoder differs from "
            "canonical preservation copy"
        )
    if d3_lock.get(
        "certified_decoder_sha256"
    ) != decoder_sha:
        raise RuntimeError(
            "decoder differs from D3"
        )
    if float(
        d3_lock.get("A1_margin_threshold")
    ) != A1_MARGIN_THRESHOLD:
        raise RuntimeError(
            "A1 margin differs from D3"
        )

    total_chunks = math.ceil(
        EXPECTED_ITEMS / CHUNK_SIZE
    )
    contract = {
        "stage": STAGE,
        "campaign_label": CAMPAIGN_LABEL,
        "items": EXPECTED_ITEMS,
        "chunk_size": CHUNK_SIZE,
        "chunk_count": total_chunks,
        "row_order": (
            "D1_validation_dataset_index_ascending"
        ),
        "D1_export_path": str(
            d1_export_path
        ),
        "D1_export_sha256": export_sha,
        "certified_decoder_path": str(
            decoder_path
        ),
        "certified_decoder_sha256": (
            decoder_sha
        ),
        "A1_margin_threshold": (
            A1_MARGIN_THRESHOLD
        ),
        "threshold_tuning_performed": False,
        "beam_decoder_selected": False,
        "test_accessed": False,
    }
    if contract_path.is_file():
        existing_contract = json.loads(
            contract_path.read_text(
                encoding="utf-8"
            )
        )
        if existing_contract != contract:
            raise RuntimeError(
                "D4 execution contract changed"
            )
    else:
        atomic_json(
            contract_path,
            contract,
        )

    with np.load(
        d1_export_path,
        allow_pickle=False,
    ) as loaded:
        source_arrays = {
            key: loaded[key].copy()
            for key in loaded.files
        }

    required_shapes = {
        "attack_logits": (EXPECTED_ITEMS,),
        "count_logits": (EXPECTED_ITEMS, 4),
        "source_logits": (
            EXPECTED_ITEMS,
            ROUTER_COUNT,
        ),
        "transit_logits": (
            EXPECTED_ITEMS,
            ROUTER_COUNT,
        ),
        "victim_logits": (
            EXPECTED_ITEMS,
            ROUTER_COUNT,
        ),
        "path_logits": (
            EXPECTED_ITEMS,
            ROUTER_COUNT,
        ),
        "y_attack": (EXPECTED_ITEMS,),
        "y_attacker_count": (
            EXPECTED_ITEMS,
        ),
        "y_source": (
            EXPECTED_ITEMS,
            ROUTER_COUNT,
        ),
        "y_transit": (
            EXPECTED_ITEMS,
            ROUTER_COUNT,
        ),
        "y_victim": (
            EXPECTED_ITEMS,
            ROUTER_COUNT,
        ),
        "y_attack_path": (
            EXPECTED_ITEMS,
            ROUTER_COUNT,
        ),
    }
    for key, expected_shape in required_shapes.items():
        if key not in source_arrays:
            raise RuntimeError(
                f"D1 export missing {key}"
            )
        if source_arrays[key].shape != expected_shape:
            raise RuntimeError(
                f"{key} shape="
                f"{source_arrays[key].shape}, "
                f"expected={expected_shape}"
            )

    if str(repo) not in sys.path:
        sys.path.insert(0, str(repo))
    decoder = importlib.import_module(
        "src.decoders."
        "v5_legal_xy_exact_decoder_certified"
    )

    completed_chunks = 0
    reused_chunks = 0
    all_chunks: list[
        dict[str, np.ndarray]
    ] = []

    for chunk_id, start, stop in chunk_ranges(
        EXPECTED_ITEMS
    ):
        chunk_path, manifest_path = chunk_paths(
            working_dir,
            chunk_id,
            start,
            stop,
        )
        try:
            chunk = validate_chunk(
                chunk_path,
                manifest_path,
                start,
                stop,
                decoder_sha,
                export_sha,
            )
        except FileNotFoundError:
            print(
                f"D4_chunk={chunk_id + 1}/"
                f"{total_chunks} "
                f"status=DECODING "
                f"items={start}:{stop}",
                flush=True,
            )
            try:
                chunk, schema_value = decode_chunk(
                    decoder,
                    source_arrays,
                    start,
                    stop,
                    schema_path,
                )
            except Exception as exc:
                atomic_json(
                    failure_path,
                    {
                        "stage": STAGE,
                        "status": "INTERRUPTED_OR_FAILED",
                        "created_utc": datetime.now(
                            timezone.utc
                        ).isoformat(),
                        "chunk_id": chunk_id,
                        "start": start,
                        "stop": stop,
                        "exception_type": type(
                            exc
                        ).__name__,
                        "exception": repr(exc),
                        "completed_chunks_before_failure": (
                            completed_chunks
                            + reused_chunks
                        ),
                        "resume_policy": (
                            "rerun exact same launcher; "
                            "completed hash-valid chunks "
                            "will be reused"
                        ),
                        "test_accessed": False,
                    },
                )
                raise

            atomic_npz(
                chunk_path,
                chunk,
            )
            manifest = {
                "stage": STAGE,
                "status": "COMPLETE",
                "chunk_id": chunk_id,
                "start": start,
                "stop": stop,
                "item_count": stop - start,
                "chunk_path": str(
                    chunk_path
                ),
                "chunk_sha256": sha256_file(
                    chunk_path
                ),
                "D1_export_sha256": export_sha,
                "certified_decoder_sha256": (
                    decoder_sha
                ),
                "A1_margin_threshold": (
                    A1_MARGIN_THRESHOLD
                ),
                "all_structural_legal": True,
                "test_accessed": False,
            }
            atomic_json(
                manifest_path,
                manifest,
            )
            chunk = validate_chunk(
                chunk_path,
                manifest_path,
                start,
                stop,
                decoder_sha,
                export_sha,
            )
            completed_chunks += 1
            print(
                f"D4_chunk={chunk_id + 1}/"
                f"{total_chunks} "
                f"status=COMMITTED "
                f"sha256={sha256_file(chunk_path)}",
                flush=True,
            )
        else:
            reused_chunks += 1
            print(
                f"D4_chunk={chunk_id + 1}/"
                f"{total_chunks} "
                f"status=REUSED",
                flush=True,
            )
        all_chunks.append(chunk)

    merged = {
        key: np.concatenate(
            [chunk[key] for chunk in all_chunks],
            axis=0,
        )
        for key in all_chunks[0]
    }
    if merged["dataset_index"].shape != (
        EXPECTED_ITEMS,
    ):
        raise RuntimeError(
            "merged D4 item count mismatch"
        )
    if not np.array_equal(
        merged["dataset_index"],
        np.arange(
            EXPECTED_ITEMS,
            dtype=np.int32,
        ),
    ):
        raise RuntimeError(
            "merged D4 coverage is not contiguous"
        )
    if not np.all(
        merged["structural_legal"] == 1
    ):
        raise RuntimeError(
            "merged D4 legality failure"
        )

    atomic_npz(
        final_outputs_path,
        merged,
    )

    labels = {
        "graph": source_arrays[
            "y_attack"
        ].astype(np.uint8),
        "count": source_arrays[
            "y_attacker_count"
        ].astype(np.int8),
        "source": source_arrays[
            "y_source"
        ].astype(np.uint8),
        "transit": source_arrays[
            "y_transit"
        ].astype(np.uint8),
        "victim": source_arrays[
            "y_victim"
        ].astype(np.uint8),
        "path": source_arrays[
            "y_attack_path"
        ].astype(np.uint8),
    }
    role_predictions = {
        role: merged[
            f"{role}_prediction"
        ]
        for role in (
            "source",
            "transit",
            "victim",
            "path",
        )
    }
    active_truth = (
        labels["graph"] == 1
    )

    graph_metrics = binary_metrics(
        merged["graph_prediction"],
        labels["graph"],
    )
    graph_metrics[
        "margin_auroc"
    ] = binary_auroc(
        merged["margin"],
        labels["graph"],
    )
    graph_metrics[
        "margin_average_precision"
    ] = average_precision(
        merged["margin"],
        labels["graph"],
    )

    metrics = {
        "graph": graph_metrics,
        "count_active": count_metrics(
            merged["count_prediction"],
            labels["count"],
            active_truth,
        ),
        "roles": {
            role: role_metrics(
                role_predictions[role],
                labels[role],
                active_truth,
            )
            for role in (
                "source",
                "transit",
                "victim",
                "path",
            )
        },
        "strict": strict_metrics(
            merged["graph_prediction"],
            merged["count_prediction"],
            role_predictions,
            labels,
        ),
        "legality": {
            "audit_semantics": (
                "route legality certified by exact decoder; evaluator "
                "checks union-valid structural invariants"
            ),
            "source_victim_overlap_items": int(
                np.sum(
                    np.any(
                        role_predictions["source"].astype(bool)
                        & role_predictions["victim"].astype(bool),
                        axis=1,
                    )
                )
            ),
            "transit_endpoint_overlap_items": int(
                np.sum(
                    np.any(
                        role_predictions["transit"].astype(bool)
                        & (
                            role_predictions["source"].astype(bool)
                            | role_predictions["victim"].astype(bool)
                        ),
                        axis=1,
                    )
                )
            ),
            "certified_decoder_items": (
                EXPECTED_ITEMS
            ),
            "certification_exceptions": 0,
            "structural_legal_items": int(
                merged[
                    "structural_legal"
                ].sum()
            ),
            "structural_legality_rate": float(
                merged[
                    "structural_legal"
                ].mean()
            ),
            "route_legal_by_certified_decoder": (
                True
            ),
        },
        "timing": {
            "mean_seconds": float(
                merged[
                    "decode_seconds"
                ].mean()
            ),
            "median_seconds": float(
                np.median(
                    merged[
                        "decode_seconds"
                    ]
                )
            ),
            "p95_seconds": float(
                np.quantile(
                    merged[
                        "decode_seconds"
                    ],
                    0.95,
                )
            ),
            "p99_seconds": float(
                np.quantile(
                    merged[
                        "decode_seconds"
                    ],
