    except SealedTestAccessError:
        test_negative_check = True
    else:
        test_negative_check = False
    if not test_negative_check:
        raise RuntimeError("guarded loader failed to reject A_test")

    validation_dataset = GuardedDataset(
        data_root,
        "validation",
        active_only=False,
