    for role in ("source", "transit", "victim", "path"):
        comparisons[f"{role}_average_precision"] = (
            role_metrics[role]["average_precision"],
            float(
                a5_metrics["roles"][role][
                    "average_precision_raw_logits"
                ]
            ),
