        comparisons[f"{role}_exact_active"] = (
            role_metrics[role]["exact_active_at_0p5"],
            float(a5_metrics["roles"][role]["exact_active"]),
        )

    metric_deltas = {
        key: abs(exported - reference)
        for key, (exported, reference) in comparisons.items()
    }
    maximum_metric_delta = max(metric_deltas.values())
    metric_consistency_pass = (
        maximum_metric_delta <= METRIC_TOLERANCE
    )
    if not metric_consistency_pass:
        raise RuntimeError(
            "export metrics differ from A5 stable replay: "
            f"max_delta={maximum_metric_delta}; "
            f"deltas={metric_deltas}"
        )

    atomic_npz(export_path, arrays)
    atomic_csv(metadata_path, metadata_rows)

    array_manifest = {
        key: {
            "shape": list(value.shape),
            "dtype": str(value.dtype),
            "finite": (
                bool(np.isfinite(value).all())
                if np.issubdtype(value.dtype, np.number)
                else None
            ),
        }
        for key, value in arrays.items()
    }
    manifest = {
        "stage": STAGE,
        "status": "FROZEN_BY_HASH",
        "created_utc": datetime.now(timezone.utc).isoformat(),
        "campaign_label": CAMPAIGN_LABEL,
        "split": "validation",
        "row_order": "guarded_validation_dataset_index_ascending",
        "items": EXPECTED_ITEMS,
        "model_checkpoint_epoch": 14,
        "parameter_count": parameter_count,
        "input_features": 70,
        "arrays": array_manifest,
        "export_path": str(export_path),
        "export_sha256": sha256_file(export_path),
        "metadata_path": str(metadata_path),
        "metadata_sha256": sha256_file(metadata_path),
        "metric_replay": {
            "selection_score": selection_score,
            "selection_components": selection_components,
            "graph_threshold_0p5": graph_metrics,
            "count_macro_f1": count_macro_f1,
            "roles": role_metrics,
            "maximum_absolute_delta_vs_A5": maximum_metric_delta,
            "tolerance": METRIC_TOLERANCE,
            "consistency_pass": metric_consistency_pass,
        },
        "decoder_executed": False,
        "threshold_tuning_performed": False,
        "test_accessed": False,
    }
    atomic_json(manifest_path, manifest)

    # Reopen the frozen export without pickle and recheck names/shapes.
    with np.load(export_path, allow_pickle=False) as reopened:
        reopened_names = sorted(reopened.files)
        expected_names = sorted(arrays)
        if reopened_names != expected_names:
            raise RuntimeError

def threshold_metrics(probabilities, targets) -> dict[str, float]:
    p = np.asarray(probabilities, dtype=np.float64).reshape(-1); y = np.asarray(targets, dtype=np.int64).reshape(-1)
    pred = (p >= 0.5).astype(np.int64)
    tp = int(((pred == 1) & (y == 1)).sum()); fp = int(((pred == 1) & (y == 0)).sum())
    fn = int(((pred == 0) & (y == 1)).sum()); tn = int(((pred == 0) & (y == 0)).sum())
    precision = tp/(tp+fp) if tp+fp else 0.0; recall = tp/(tp+fn) if tp+fn else 0.0
    f1 = 2*precision*recall/(precision+recall) if precision+recall else 0.0
    return {'accuracy': (tp+tn)/max(1,tp+fp+fn+tn), 'precision': precision, 'recall': recall,
            'f1': f1, 'fpr': fp/(fp+tn) if fp+tn else 0.0, 'tp': tp, 'fp': fp, 'fn': fn, 'tn': tn}

def sha(path: Path) -> str:
    h = hashlib.sha256()
    with path.open('rb') as f:
        for block in iter(lambda: f.read(1024 * 1024), b''):
            h.update(block)
    return h.hexdigest()

def move(batch, device):
    mapping = {'x':('x',torch.float32), 'mask':('physical_port_mask',torch.float32),
               'graph':('y_attack',torch.float32), 'count':('y_attacker_count',torch.long),
               'source':('y_source',torch.float32), 'transit':('y_transit',torch.float32),
               'victim':('y_victim',torch.float32), 'path':('y_attack_path',torch.float32)}
    out = {}
    for dst,(src,dtype) in mapping.items():
        if src not in batch: raise RuntimeError(f'missing {src}; keys={sorted(batch)}')
        value = batch[src].to(device=device, dtype=dtype, non_blocking=device.type=='cuda')
        out[dst] = value.reshape(-1) if dst in ('graph','count') else value
    return out

def macro_f1(predictions, targets) -> float:
    pred = np.asarray(predictions); y = np.asarray(targets); values = []
    for c in (1,2,3,4):
        pp, yy = pred == c, y == c
        tp = int((pp & yy).sum()); fp = int((pp & ~yy).sum()); fn = int((~pp & yy).sum())
        precision = tp/(tp+fp) if tp+fp else 0.0; recall = tp/(tp+fn) if tp+fn else 0.0
        values.append(2*precision*recall/(precision+recall) if precision+recall else 0.0)
    return float(np.mean(values))

def import_file(path: Path, name: str):
    spec = importlib.util.spec_from_file_location(name, path)
    if spec is None or spec.loader is None: raise RuntimeError(f'cannot import {path}')
    mod = importlib.util.module_from_spec(spec); sys.modules[name] = mod; spec.loader.exec_module(mod)
    return mod

def exact_active(probabilities, targets, active) -> float:
    pred = (np.asarray(probabilities) >= 0.5).astype(np.int64); y = np.asarray(targets, dtype=np.int64)
    return float(np.mean(np.all(pred[active] == y[active], axis=1)))

def auroc(scores, targets) -> float:
    s = np.asarray(scores, dtype=np.float64).reshape(-1); y = np.asarray(targets, dtype=np.int64).reshape(-1)
    pos = y == 1; neg = y == 0; np_, nn_ = int(pos.sum()), int(neg.sum())
    if np_ == 0 or nn_ == 0: return float('nan')
    return float((ranks(s)[pos].sum() - np_ * (np_ + 1) / 2.0) / (np_ * nn_))

def ap(scores, targets) -> float:
    s = np.asarray(scores, dtype=np.float64).reshape(-1); y = np.asarray(targets, dtype=np.int64).reshape(-1)
    npos = int((y == 1).sum())
    if npos == 0: return float('nan')
    order = np.argsort(-s, kind='mergesort'); yy = y[order]
    precision = np.cumsum(yy == 1) / np.arange(1, len(yy) + 1)
    return float(precision[yy == 1].sum() / npos)

def gate_pass(
    initial_losses: dict[str, float],
    final_losses: dict[str, float],
    metrics: dict[str, Any],
) -> tuple[bool, dict[str, bool]]:
    checks = {
        "total_loss_ratio_le_0p25": (
            final_losses["total"]
            <= 0.25 * initial_losses["total"]
        ),
        "every_component_loss_decreased": all(
            final_losses[name] < initial_losses[name]
            for name in (
                "graph",
                "count",
                "source",
                "transit",
                "victim",
                "path",
            )
        ),
        "graph_accuracy_ge_0p95": (
            metrics["graph"]["accuracy"] >= 0.95
        ),
        "count_accuracy_ge_0p90": (
            metrics["count_active_accuracy"] >= 0.90
        ),
        "source_f1_ge_0p85": metrics["source"]["f1"] >= 0.85,
        "transit_f1_ge_0p85": metrics["transit"]["f1"] >= 0.85,
        "victim_f1_ge_0p85": metrics["victim"]["f1"] >= 0.85,
        "path_f1_ge_0p85": metrics["path"]["f1"] >= 0.85,
    }
    return all(checks.values()), checks

def seed_all(seed: int):
    random.seed(seed); np.random.seed(seed); torch.manual_seed(seed); torch.cuda.manual_seed_all(seed)
    if torch.cuda.is_available():
        torch.backends.cudnn.deterministic = True
        torch.backends.cudnn.benchmark = False

def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()

def select_probe_indices(dataset, d0_report_path: Path) -> list[int]:
    if d0_report_path.is_file():
        report = json.loads(d0_report_path.read_text(encoding="utf-8"))
        indices = report.get("data", {}).get("probe_indices")
        if indices is not None and len(indices) == 8:
            return [int(index) for index in indices]

    inactive = []
    active_by_count: dict[int, int] = {}
    for index in range(len(dataset)):
        sample = dataset[index]
        graph = int(torch.as_tensor(sample["y_attack"]).item())
        count = int(torch.as_tensor(sample["y_attacker_count"]).item())
        if graph == 0 and len(inactive) < 4:
            inactive.append(index)
        if graph == 1 and count in (1, 2, 3, 4):
            active_by_count.setdefault(count, index)
        if len(inactive) == 4 and sorted(active_by_count) == [1, 2, 3, 4]:
            return inactive + [active_by_count[value] for value in (1, 2, 3, 4)]
    raise RuntimeError("could not select 4 inactive and K1-K4 validation probes")

def safe_metadata(sample: dict[str, Any], key: str) -> Any:
    if key not in sample:
        return None
    value = sample[key]
    if isinstance(value, torch.Tensor):
        value = value.detach().cpu()
        if value.numel() == 1:
            return value.item()
        return value.tolist()
    if isinstance(value, np.ndarray):
        return value.tolist()
    if isinstance(value, np.generic):
        return value.item()
    if isinstance(value, (str, int, float, bool)) or value is None:
        return value
    return str(value)

def validate_chunk(
    chunk_path: Path,
    manifest_path: Path,
    expected_start: int,
    expected_stop: int,
    decoder_sha256: str,
    export_sha256: str,
) -> dict[str, np.ndarray]:
    if not chunk_path.is_file() or not manifest_path.is_file():
        raise FileNotFoundError

    manifest = json.loads(
        manifest_path.read_text(encoding="utf-8")
    )
    if manifest.get("status") != "COMPLETE":
        raise RuntimeError(
            f"chunk manifest not COMPLETE: {manifest_path}"
        )
    if int(manifest.get("start", -1)) != expected_start:
        raise RuntimeError(
            f"chunk start changed: {manifest_path}"
        )
    if int(manifest.get("stop", -1)) != expected_stop:
        raise RuntimeError(
            f"chunk stop changed: {manifest_path}"
        )
    if manifest.get(
        "certified_decoder_sha256"
    ) != decoder_sha256:
        raise RuntimeError(
            f"decoder hash changed for {manifest_path}"
        )
    if manifest.get(
        "D1_export_sha256"
    ) != export_sha256:
        raise RuntimeError(
            f"D1 export hash changed for {manifest_path}"
        )
    if float(
        manifest.get("A1_margin_threshold")
    ) != A1_MARGIN_THRESHOLD:
        raise RuntimeError(
            f"A1 margin changed for {manifest_path}"
        )
    if manifest.get("chunk_sha256") != sha256_file(
        chunk_path
    ):
        raise RuntimeError(
            f"chunk SHA mismatch: {chunk_path}"
        )

    with np.load(
        chunk_path,
        allow_pickle=False,
    ) as loaded:
        arrays = {
            key: loaded[key].copy()
            for key in loaded.files
        }

    expected_items = expected_stop - expected_start
    expected_shapes = {
        "dataset_index": (expected_items,),
        "margin": (expected_items,),
        "graph_prediction": (expected_items,),
        "count_prediction": (expected_items,),
        "source_prediction": (
            expected_items,
            ROUTER_COUNT,
        ),
        "transit_prediction": (
            expected_items,
            ROUTER_COUNT,
        ),
        "victim_prediction": (
            expected_items,
            ROUTER_COUNT,
        ),
        "path_prediction": (
            expected_items,
            ROUTER_COUNT,
        ),
        "route_count": (expected_items,),
        "decode_seconds": (expected_items,),
        "structural_legal": (expected_items,),
    }
    for key, expected_shape in expected_shapes.items():
        if key not in arrays:
            raise RuntimeError(
                f"chunk missing {key}: {chunk_path}"
            )
        if arrays[key].shape != expected_shape:
            raise RuntimeError(
                f"{key} shape={arrays[key].shape}, "
                f"expected={expected_shape}"
            )

    expected_indices = np.arange(
        expected_start,
        expected_stop,
        dtype=np.int32,
    )
    if not np.array_equal(
        arrays["dataset_index"],
        expected_indices,
    ):
        raise RuntimeError(
            f"chunk index coverage changed: {chunk_path}"
        )
    if not np.isfinite(arrays["margin"]).all():
        raise RuntimeError(
            f"non-finite margin in {chunk_path}"
        )
    if not np.isfinite(
        arrays["decode_seconds"]
    ).all():
        raise RuntimeError(
            f"non-finite timing in {chunk_path}"
        )
    if not np.all(
        arrays["structural_legal"] == 1
    ):
        raise RuntimeError(
            f"structural legality failure in {chunk_path}"
        )
    return arrays

def strict_metrics(
    graph_prediction: np.ndarray,
    count_prediction: np.ndarray,
    role_predictions: dict[str, np.ndarray],
    labels: dict[str, np.ndarray],
) -> dict[str, Any]:
    graph_truth = labels["graph"]
    active_truth = graph_truth == 1
    graph_correct = (
        graph_prediction == graph_truth
    )
    role_correct = np.ones(
        graph_truth.shape[0],
        dtype=bool,
    )
    roles_empty = np.ones(
        graph_truth.shape[0],
        dtype=bool,
    )
    for role in (
        "source",
        "transit",
        "victim",
        "path",
    ):
        role_correct &= np.all(
            role_predictions[role]
            == labels[role],
            axis=1,
        )
        roles_empty &= np.all(
            role_predictions[role] == 0,
            axis=1,
        )

    active_exact = (
        active_truth
        & graph_correct
        & (
            count_prediction
            == labels["count"]
        )
        & role_correct
    )
    inactive_exact = (
        (~active_truth)
        & graph_correct
        & roles_empty
    )
    strict = active_exact | inactive_exact
    return {
        "strict_all_task_exactness": float(
            strict.mean()
        ),
        "strict_active_exactness": float(
            active_exact[
                active_truth
            ].mean()
        ),
        "strict_inactive_exactness": float(
            inactive_exact[
                ~active_truth
            ].mean()
        ),
        "strict_exact_items": int(
            strict.sum()
        ),
        "strict_active_exact_items": int(
            active_exact.sum()
        ),
        "strict_inactive_exact_items": int(
            inactive_exact.sum()
        ),
    }

def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()

def scalar_int(value: Any) -> int:
    if isinstance(value, bool):
        return int(value)
    if isinstance(value, (int, np.integer)):
        return int(value)
    if isinstance(value, float):
        if math.isfinite(value) and float(value).is_integer():
            return int(value)
    if isinstance(value, str):
        return int(value)
    raise ValueError(f"cannot convert count field to int: {value!r}")

def scalar_bool(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, np.integer)):
        return bool(int(value))
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError("non-finite graph scalar")
        if value in (0.0, 1.0):
            return bool(int(value))
    if isinstance(value, str):
        lowered = value.strip().lower()
        if lowered in {"true", "attack", "active", "1"}:
            return True
        if lowered in {"false", "normal", "inactive", "0"}:
            return False
    raise ValueError(f"cannot convert graph field to bool: {value!r}")

def route_ids_vector(value: Any) -> np.ndarray:
    if value is None:
        return np.empty(0, dtype=np.int32)
    array = np.asarray(value)
    if array.ndim == 0:
        scalar = int(array.item())
        return np.asarray([scalar], dtype=np.int32)
    return np.asarray(
        [int(item) for item in array.reshape(-1).tolist()],
        dtype=np.int32,
    )

def role_metrics(
    prediction: np.ndarray,
    target: np.ndarray,
    active_truth: np.ndarray,
) -> dict[str, Any]:
    flattened = binary_metrics(
        prediction.reshape(-1),
        target.reshape(-1),
    )
    return {
        "flattened": flattened,
        "exact_all": float(
            np.mean(
                np.all(
                    prediction == target,
                    axis=1,
                )
            )
        ),
        "exact_active": float(
            np.mean(
                np.all(
                    prediction[active_truth]
                    == target[active_truth],
                    axis=1,
                )
            )
        ),
        "exact_inactive": float(
            np.mean(
                np.all(
                    prediction[~active_truth]
                    == target[~active_truth],
                    axis=1,
                )
            )
        ),
        "mean_predicted_cardinality_active": float(
            prediction[
                active_truth
            ].sum(axis=1).mean()
        ),
        "mean_true_cardinality_active": float(
            target[
                active_truth
            ].sum(axis=1).mean()
        ),
    }

def resolve_field(
    document: dict[str, Any],
    semantic_name: str,
) -> tuple[Any, str]:
    aliases = {
        normalized_key(alias)
        for alias in FIELD_ALIASES[semantic_name]
    }

    # Prefer the top-level decoded-output contract.
    for key, value in document.items():
        if normalized_key(str(key)) in aliases:
            return value, f"$.{key}"

    candidates: list[tuple[int, str, Any]] = []
    for path, mapping in iter_mapping_nodes(document):
        depth = path.count(".") + path.count("[")
        for key, value in mapping.items():
            if normalized_key(str(key)) in aliases:
                candidates.append(
                    (depth, f"{path}.{key}", value)
                )
    if not candidates:
        raise KeyError(
            f"cannot resolve {semantic_name}; "
            f"top-level keys={sorted(document)}"
        )
    candidates.sort(key=lambda item: (item[0], item[1]))
    _, path, value = candidates[0]
    return value, path

def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument("--repo", required=True)
    parser.add_argument("--output-dir", required=True)
    parser.add_argument("--installed-script", required=True)
    return parser.parse_args()

def normalized_key(value: str) -> str:
    return "".join(
        character.lower()
        for character in value
        if character.isalnum() or character == "_"
    )

def mask_vector(value: Any) -> np.ndarray:
    if isinstance(value, dict):
        # Common serialized forms: {"mask": ...} or
        # {"bits": [...]}.
        for key in ("mask", "bitmap", "bits", "value"):
            if key in value:
                return mask_vector(value[key])

    if isinstance(value, (int, np.integer)):
        integer = int(value)
        if integer < 0 or integer >= (1 << ROUTER_COUNT):
            raise ValueError(
                f"integer mask out of range: {integer}"
            )
        return np.asarray(
            [
                (integer >> router) & 1
                for router in range(ROUTER_COUNT)
            ],
            dtype=np.uint8,
        )

    array = np.asarray(value)
    if array.ndim == 0:
        return mask_vector(array.item())
    flat = array.reshape(-1)
    if flat.size == ROUTER_COUNT:
        if not np.all(np.isin(flat, [0, 1, False, True])):
            raise ValueError(
                f"16-element mask is not binary: {flat.tolist()}"
            )
        return flat.astype(np.uint8)

    # A short list of router IDs is also accepted.
    if flat.size <= ROUTER_COUNT:
        try:
            indices = [int(item) for item in flat.tolist()]
        except Exception as exc:
            raise ValueError(
                f"cannot interpret mask value: {value!r}"
            ) from exc
        if len(indices) != len(set(indices)):
            raise ValueError(
                f"duplicate router IDs in mask: {indices}"
            )
        if all(0 <= item < ROUTER_COUNT for item in indices):
            result = np.zeros(ROUTER_COUNT, dtype=np.uint8)
            result[indices] = 1
            return result

    raise ValueError(
        f"cannot convert mask to {ROUTER_COUNT} bits: {value!r}"
    )

def jsonable(value: Any) -> Any:
    if dataclasses.is_dataclass(value):
        return jsonable(dataclasses.asdict(value))
    if isinstance(value, dict):
        return {
            str(key): jsonable(item)
            for key, item in value.items()
        }
    if isinstance(value, (list, tuple)):
        return [jsonable(item) for item in value]
    if isinstance(value, np.ndarray):
        return value.tolist()
    if isinstance(value, np.generic):
        return value.item()
    if isinstance(value, Path):
        return str(value)
    if isinstance(value, float):
        if not math.isfinite(value):
            raise RuntimeError(
                f"non-finite value in decoder object: {value}"
            )
        return value
    if isinstance(value, (str, int, bool)) or value is None:
        return value
    if hasattr(value, "__dict__"):
        return {
            key: jsonable(item)
            for key, item in vars(value).items()
            if not key.startswith("_")
        }
    return repr(value)

def extract_decoded_output(
    decoded: Any,
    hypothesis: Any,
) -> tuple[dict[str, Any], dict[str, str]]:
    decoded_document = jsonable(decoded)
    hypothesis_document = jsonable(hypothesis)
    if not isinstance(decoded_document, dict):
        raise RuntimeError(
            "decoded output is not mapping-like: "
            f"{type(decoded_document)}"
        )
    if not isinstance(hypothesis_document, dict):
        raise RuntimeError(
            "hypothesis is not mapping-like: "
            f"{type(hypothesis_document)}"
        )

    paths: dict[str, str] = {}

    graph_value, paths["graph"] = resolve_field(
        decoded_document,
        "graph",
    )
    graph = scalar_bool(graph_value)

    masks = {}
    for role in ("source", "transit", "victim", "path"):
        try:
            value, paths[role] = resolve_field(
                decoded_document,
                role,
            )
        except KeyError:
            if not graph:
                masks[role] = np.zeros(
                    ROUTER_COUNT,
                    dtype=np.uint8,
                )
                paths[role] = (
                    "$.<implicit_zero_for_normal_output>"
                )
                continue
            value, paths[role] = resolve_field(
                hypothesis_document,
                role,
            )
        masks[role] = mask_vector(value)

    try:
        count_value, paths["count"] = resolve_field(
            decoded_document,
            "count",
        )
        count = scalar_int(count_value)
    except KeyError:
        if graph:
            count = int(masks["source"].sum())
            paths["count"] = "$.<derived_from_source_mask>"
        else:
            count = 0
            paths["count"] = "$.<implicit_zero_for_normal_output>"

    try:
        route_value, paths["route_ids"] = resolve_field(
            decoded_document,
            "route_ids",
        )
    except KeyError:
        try:
            route_value, paths["route_ids"] = resolve_field(
                hypothesis_document,
                "route_ids",
            )
        except KeyError:
            route_value = []
            paths["route_ids"] = "$.<not_exposed>"
    route_ids = route_ids_vector(route_value)

    try:
        margin_value, paths["margin"] = resolve_field(
            hypothesis_document,
            "margin",
        )
        margin = float(margin_value)
    except KeyError:
        margin = float(getattr(hypothesis, "margin"))
        paths["margin"] = "$.<hypothesis_attribute>"

    if not math.isfinite(margin):
        raise RuntimeError("decoder produced non-finite margin")

    if not graph:
        if count != 0:
            raise RuntimeError(
                f"normal decoded output has count={count}"
            )
        if any(int(mask.sum()) != 0 for mask in masks.values()):
            raise RuntimeError(
                "normal decoded output has non-empty role masks"
            )
        route_ids = np.empty(0, dtype=np.int32)
    else:
        if count not in (1, 2, 3, 4):
            raise RuntimeError(
                f"attack decoded output has invalid count={count}"
            )

    return {
        "graph": np.uint8(graph),
        "count": np.int8(count),
        "source": masks["source"],
        "transit": masks["transit"],
        "victim": masks["victim"],
        "path": masks["path"],
        "route_ids": route_ids,
        "margin": np.float64(margin),
        "decoded_document": decoded_document,
        "hypothesis_document": hypothesis_document,
    }, paths

def decode_chunk(
    decoder,
    arrays: dict[str, np.ndarray],
    start: int,
    stop: int,
    schema_artifact_path: Path,
) -> tuple[dict[str, np.ndarray], dict[str, Any]]:
    item_count = stop - start
    output = {
        "dataset_index": np.arange(
            start,
            stop,
            dtype=np.int32,
        ),
        "margin": np.empty(
            item_count,
            dtype=np.float64,
        ),
        "graph_prediction": np.empty(
            item_count,
            dtype=np.uint8,
        ),
        "count_prediction": np.empty(
            item_count,
            dtype=np.int8,
        ),
        "source_prediction": np.empty(
            (item_count, ROUTER_COUNT),
            dtype=np.uint8,
        ),
        "transit_prediction": np.empty(
            (item_count, ROUTER_COUNT),
            dtype=np.uint8,
        ),
        "victim_prediction": np.empty(
            (item_count, ROUTER_COUNT),
            dtype=np.uint8,
        ),
        "path_prediction": np.empty(
            (item_count, ROUTER_COUNT),
            dtype=np.uint8,
        ),
        "route_count": np.empty(
            item_count,
            dtype=np.int8,
        ),
        "decode_seconds": np.empty(
            item_count,
            dtype=np.float64,
        ),
        "structural_legal": np.empty(
            item_count,
            dtype=np.uint8,
        ),
    }
    schema_value = None

    for local, dataset_index in enumerate(
        range(start, stop)
    ):
        started = time.perf_counter()
        hypothesis = (
            decoder.decode_best_attack_hypothesis(
                float(
                    arrays["attack_logits"][
                        dataset_index
                    ]
                ),
                arrays["count_logits"][
                    dataset_index
                ].astype(np.float64),
                arrays["source_logits"][
                    dataset_index
                ].astype(np.float64),
                arrays["transit_logits"][
                    dataset_index
                ].astype(np.float64),
                arrays["victim_logits"][
                    dataset_index
                ].astype(np.float64),
                arrays["path_logits"][
                    dataset_index
                ].astype(np.float64),
            )
        )
        decoded = decoder.apply_margin_threshold(
            hypothesis,
            A1_MARGIN_THRESHOLD,
        )
        elapsed = time.perf_counter() - started

        extracted, paths = extract_decoded_output(
            decoded,
            hypothesis,
        )
        legality = structural_legality(
            int(extracted["graph"]),
            int(extracted["count"]),
            extracted["source"],
            extracted["transit"],
            extracted["victim"],
            extracted["path"],
            extracted["route_ids"],
        )
        if not legality["all_structural_checks"]:
            raise RuntimeError(
                "A1 structural legality failure at "
                f"dataset_index={dataset_index}: "
                f"{legality}"
            )

        output["margin"][local] = (
            extracted["margin"]
        )
        output["graph_prediction"][local] = (
            extracted["graph"]
        )
        output["count_prediction"][local] = (
            extracted["count"]
        )
        for role in (
            "source",
            "transit",
            "victim",
            "path",
        ):
            output[f"{role}_prediction"][
                local
            ] = extracted[role]
        output["route_count"][local] = int(
            extracted["route_ids"].size
        )
        output["decode_seconds"][local] = elapsed
        output["structural_legal"][local] = 1

        if schema_value is None:
            schema_value = {
                "stage": STAGE,
                "dataset_index": dataset_index,
                "resolved_paths": paths,
                "decoded_top_level_keys": sorted(
                    extracted[
                        "decoded_document"
                    ]
                ),
                "hypothesis_top_level_keys": sorted(
                    extracted[
                        "hypothesis_document"
                    ]
                ),
                "decoded_example": extracted[
                    "decoded_document"
                ],
                "hypothesis_example": extracted[
                    "hypothesis_document"
                ],
            }
            if not schema_artifact_path.is_file():
                atomic_json(
                    schema_artifact_path,
                    schema_value,
                )

        if (
            local == 0
            or (local + 1) % 20 == 0
            or local + 1 == item_count
        ):
            print(
                f"chunk_item={local + 1}/"
                f"{item_count} "
                f"dataset_index={dataset_index} "
                f"seconds={elapsed:.6f}",
                flush=True,
            )

    if schema_value is None:
        raise RuntimeError("empty chunk")
    return output, schema_value

def count_metrics(
    prediction: np.ndarray,
    target: np.ndarray,
    active_truth: np.ndarray,
) -> dict[str, Any]:
    prediction = prediction[active_truth].astype(
        np.int64
    )
    target = target[active_truth].astype(
        np.int64
    )
    per_class = {}
    f1_values = []
    for class_value in (1, 2, 3, 4):
        pred_positive = (
            prediction == class_value
        )
        true_positive = (
            target == class_value
        )
        tp = int(
            np.sum(
                pred_positive & true_positive
            )
        )
        fp = int(
            np.sum(
                pred_positive & ~true_positive
            )
        )
        fn = int(
            np.sum(
                ~pred_positive & true_positive
            )
        )
        precision = (
            tp / (tp + fp)
            if tp + fp
            else 0.0
        )
        recall = (
            tp / (tp + fn)
            if tp + fn
            else 0.0
        )
        f1 = (
            2.0 * precision * recall
            / (precision + recall)
            if precision + recall
            else 0.0
        )
        f1_values.append(f1)
        per_class[str(class_value)] = {
            "precision": precision,
            "recall": recall,
            "f1": f1,
            "support": int(
                true_positive.sum()
            ),
        }
    return {
        "accuracy": float(
            np.mean(prediction == target)
        ),
        "macro_f1": float(
            np.mean(f1_values)
        ),
        "predicted_zero_rate": float(
            np.mean(prediction == 0)
        ),
        "items": int(target.size),
        "per_class": per_class,
    }

