    stem = (
        f"chunk_{chunk_id:04d}_"
        f"items_{start:05d}_{stop:05d}"
    )
    return (
        working_dir / f"{stem}.npz",
        working_dir / f"{stem}.manifest.json",
    )

def binary_metrics(
    prediction: np.ndarray,
    target: np.ndarray,
) -> dict[str, Any]:
    prediction = np.asarray(
        prediction,
        dtype=np.uint8,
    ).reshape(-1)
    target = np.asarray(
        target,
        dtype=np.uint8,
    ).reshape(-1)
    tp = int(
        np.sum(
            (prediction == 1) & (target == 1)
        )
    )
    fp = int(
        np.sum(
            (prediction == 1) & (target == 0)
        )
    )
    fn = int(
        np.sum(
            (prediction == 0) & (target == 1)
        )
    )
    tn = int(
        np.sum(
            (prediction == 0) & (target == 0)
        )
    )
    precision = (
        tp / (tp + fp) if tp + fp else 0.0
    )
    recall = (
        tp / (tp + fn) if tp + fn else 0.0
    )
    f1 = (
        2.0 * precision * recall
        / (precision + recall)
        if precision + recall
        else 0.0
    )
    return {
        "accuracy": (
            (tp + tn)
            / max(1, tp + fp + fn + tn)
        ),
        "precision": precision,
        "recall": recall,
        "f1": f1,
        "fpr": (
            fp / (fp + tn)
            if fp + tn
            else 0.0
        ),
        "tp": tp,
        "fp": fp,
        "fn": fn,
        "tn": tn,
    }

def binary_auroc(
    scores: np.ndarray,
    targets: np.ndarray,
) -> float:
    scores = np.asarray(
        scores,
        dtype=np.float64,
    ).reshape(-1)
    targets = np.asarray(
        targets,
        dtype=np.int64,
    ).reshape(-1)
    positive = targets == 1
    negative = targets == 0
    n_positive = int(positive.sum())
    n_negative = int(negative.sum())
    if n_positive == 0 or n_negative == 0:
        return float("nan")
    ranks = average_ranks(scores)
    return float(
        (
            ranks[positive].sum()
            - n_positive
            * (n_positive + 1)
            / 2.0
        )
        / (n_positive * n_negative)
    )

def average_precision(
    scores: np.ndarray,
    targets: np.ndarray,
) -> float:
    scores = np.asarray(
        scores,
        dtype=np.float64,
    ).reshape(-1)
    targets = np.asarray(
        targets,
        dtype=np.int64,
    ).reshape(-1)
    positive_count = int(
        (targets == 1).sum()
    )
    if positive_count == 0:
        return float("nan")
    order = np.argsort(
        -scores,
        kind="mergesort",
    )
    ordered = targets[order]
    cumulative = np.cumsum(ordered == 1)
    positions = np.arange(
        1,
        len(targets) + 1,
    )
    precision = cumulative / positions
    return float(
        precision[ordered == 1].sum()
        / positive_count
    )

def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()

def role_metrics(
    labels: np.ndarray,
    predictions: np.ndarray,
    scores: np.ndarray,
    active_mask: np.ndarray,
) -> dict[str, float]:
    labels = np.asarray(labels, dtype=np.uint8)
    predictions = np.asarray(predictions, dtype=np.uint8)
    scores = np.asarray(scores, dtype=np.float64)
    active_mask = np.asarray(active_mask, dtype=bool).reshape(-1)
    exact_active = float(
        np.mean(
            np.all(
                predictions[active_mask] == labels[active_mask],
                axis=1,
            )
        )
    )
    return {
        "average_precision_all_router_labels": average_precision(
            labels.reshape(-1),
            scores.reshape(-1),
        ),
        "exact_active": exact_active,
    }

def resolve_chunk_path(
    manifest_path: Path,
    manifest: dict[str, Any],
    possible_keys: tuple[str, ...],
) -> Path:
    for key in possible_keys:
        value = manifest.get(key)
        if value:
            path = Path(value)
            if not path.is_absolute():
                path = manifest_path.parent / path
            return path.resolve()
    raise RuntimeError(f"chunk path missing in {manifest_path}")

def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument("--repo", required=True)
    parser.add_argument("--output-dir", required=True)
    parser.add_argument("--installed-script", required=True)
    return parser.parse_args()

def manifest_range(path: Path, manifest: dict[str, Any]) -> tuple[int, int]:
    if "start" in manifest and "stop" in manifest:
        return int(manifest["start"]), int(manifest["stop"])
    match = re.search(r"items_(\d+)_(\d+)", path.name)
    if not match:
        raise RuntimeError(f"cannot resolve chunk range from {path}")
    return int(match.group(1)), int(match.group(2))

def load_valid_suffix_chunk(
    manifest_path: Path,
    expected: dict[str, Any],
) -> dict[str, np.ndarray] | None:
    try:
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
        for key, value in expected.items():
            if manifest.get(key) != value:
                return None
        chunk_path = resolve_chunk_path(
            manifest_path,
            manifest,
            ("chunk_path",),
        )
        if (
            manifest.get("status") != "COMPLETE"
            or not chunk_path.is_file()
            or manifest.get("chunk_sha256") != sha256_file(chunk_path)
        ):
            return None
        with np.load(chunk_path, allow_pickle=False) as loaded:
            return {key: loaded[key].copy() for key in loaded.files}
    except Exception:
        return None

def load_and_validate_canonical_prefix(
    working_dir: Path,
    export_sha: str,
    canonical_sha: str,
) -> tuple[list[dict[str, Any]], dict[str, np.ndarray]]:
    records = []
    for manifest_path in working_dir.glob("chunk_*.manifest.json"):
        try:
            manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
            start, stop = manifest_range(manifest_path, manifest)
        except Exception:
            continue
        if start >= PREFIX_ITEMS or stop > PREFIX_ITEMS:
            continue
        chunk_path = resolve_chunk_path(
            manifest_path,
            manifest,
            ("chunk_path", "canonical_chunk_path"),
        )
        expected_sha = (
            manifest.get("chunk_sha256")
            or manifest.get("canonical_chunk_sha256")
        )
        if not chunk_path.is_file():
            raise RuntimeError(f"canonical chunk missing: {chunk_path}")
        if expected_sha != sha256_file(chunk_path):
            raise RuntimeError(
                f"canonical chunk SHA mismatch: {chunk_path}"
            )
        if manifest.get("D1_export_sha256") != export_sha:
            raise RuntimeError(
                f"canonical chunk D1 export mismatch: {manifest_path}"
            )
        decoder_sha = manifest.get("certified_decoder_sha256")
        if decoder_sha is not None and decoder_sha != canonical_sha:
            raise RuntimeError(
                f"canonical decoder SHA mismatch: {manifest_path}"
            )
        records.append(
            {
                "start": start,
                "stop": stop,
                "manifest_path": manifest_path,
                "chunk_path": chunk_path,
                "chunk_sha256": expected_sha,
            }
        )

    records.sort(key=lambda row: row["start"])
    expected_start = 0
    for record in records:
        if record["start"] != expected_start:
            raise RuntimeError(
                f"canonical prefix gap: expected {expected_start}, "
                f"found {record['start']}"
            )
        expected_start = record["stop"]
    if expected_start != PREFIX_ITEMS:
        raise RuntimeError(
            f"canonical prefix ends at {expected_start}, "
            f"expected {PREFIX_ITEMS}"
        )

    fields = {
        "dataset_index": [],
        "graph_prediction": [],
        "count_prediction": [],
        "source_prediction": [],
        "transit_prediction": [],
        "victim_prediction": [],
        "path_prediction": [],
        "margin": [],
        "route_count": [],
        "selected_path_code": [],
    }

    for record in records:
        with np.load(record["chunk_path"], allow_pickle=False) as loaded:
            count = record["stop"] - record["start"]
            fields["dataset_index"].append(
                loaded["dataset_index"].copy()
                if "dataset_index" in loaded.files
                else np.arange(
                    record["start"],
                    record["stop"],
                    dtype=np.int32,
                )
            )
            for key in (
                "graph_prediction",
                "count_prediction",
                "source_prediction",
                "transit_prediction",
                "victim_prediction",
                "path_prediction",
                "margin",
                "route_count",
            ):
                if key not in loaded.files:
                    raise RuntimeError(
                        f"canonical chunk missing {key}: "
                        f"{record['chunk_path']}"
                    )
                fields[key].append(loaded[key].copy())
            fields["selected_path_code"].append(
                np.zeros(count, dtype=np.uint8)
            )

    merged = {
        key: np.concatenate(parts, axis=0)
        for key, parts in fields.items()
    }
    if merged["dataset_index"].shape[0] != PREFIX_ITEMS:
        raise RuntimeError("canonical prefix item count mismatch")
    if not np.array_equal(
        merged["dataset_index"],
        np.arange(PREFIX_ITEMS),
    ):
        raise RuntimeError("canonical prefix dataset order mismatch")
    return records, merged

def binary_auroc(labels: np.ndarray, scores: np.ndarray) -> float:
    labels = np.asarray(labels, dtype=np.uint8).reshape(-1)
    scores = np.asarray(scores, dtype=np.float64).reshape(-1)
    positives = int(np.sum(labels == 1))
    negatives = int(np.sum(labels == 0))
    if positives == 0 or negatives == 0:
        return float("nan")

    order = np.argsort(scores, kind="mergesort")
    sorted_scores = scores[order]
    ranks = np.empty(scores.size, dtype=np.float64)

    start = 0
    while start < scores.size:
        stop = start + 1
        while (
            stop < scores.size
            and sorted_scores[stop] == sorted_scores[start]
        ):
            stop += 1
        average_rank = (start + 1 + stop) / 2.0
        ranks[order[start:stop]] = average_rank
        start = stop

    positive_rank_sum = float(np.sum(ranks[labels == 1]))
    return (
        positive_rank_sum - positives * (positives + 1) / 2.0
    ) / (positives * negatives)

def average_precision(labels: np.ndarray, scores: np.ndarray) -> float:
    labels = np.asarray(labels, dtype=np.uint8).reshape(-1)
    scores = np.asarray(scores, dtype=np.float64).reshape(-1)
    positives = int(np.sum(labels == 1))
    if positives == 0:
        return float("nan")
    order = np.argsort(-scores, kind="mergesort")
    sorted_labels = labels[order]
    cumulative = np.cumsum(sorted_labels)
    ranks = np.arange(1, labels.size + 1)
    precision = cumulative / ranks
    return float(np.sum(precision * sorted_labels) / positives)

def validate_regression_chunk(
    candidate_path: Path,
    manifest_path: Path,
    start: int,
    stop: int,
    frozen_candidate_sha256: str,
    export_sha256: str,
    canonical_chunk_sha256: str,
) -> dict[str, np.ndarray]:
    if not candidate_path.is_file() or not manifest_path.is_file():
        raise FileNotFoundError
    manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    if manifest.get("status") != "COMPLETE":
        raise RuntimeError(f"regression manifest not complete: {manifest_path}")
    if int(manifest.get("start", -1)) != start:
        raise RuntimeError(f"regression start changed: {manifest_path}")
    if int(manifest.get("stop", -1)) != stop:
        raise RuntimeError(f"regression stop changed: {manifest_path}")
    if manifest.get("candidate_sha256") != frozen_candidate_sha256:
        raise RuntimeError(f"candidate hash changed: {manifest_path}")
    if manifest.get("D1_export_sha256") != export_sha256:
        raise RuntimeError(f"export hash changed: {manifest_path}")
    if manifest.get("canonical_chunk_sha256") != canonical_chunk_sha256:
        raise RuntimeError(f"canonical reference changed: {manifest_path}")
    if manifest.get("candidate_chunk_sha256") != sha256_file(candidate_path):
        raise RuntimeError(f"candidate chunk SHA mismatch: {candidate_path}")
    with np.load(candidate_path, allow_pickle=False) as loaded:
        arrays = {key: loaded[key].copy() for key in loaded.files}
    expected_items = stop - start
    expected_shapes = {
        "dataset_index": (expected_items,),
        "graph_prediction": (expected_items,),
        "count_prediction": (expected_items,),
        "source_prediction": (expected_items, 16),
        "transit_prediction": (expected_items, 16),
        "victim_prediction": (expected_items, 16),
        "path_prediction": (expected_items, 16),
        "route_count": (expected_items,),
        "margin": (expected_items,),
        "decode_seconds": (expected_items,),
        "exact_match": (expected_items,),
    }
    for key, shape in expected_shapes.items():
        if key not in arrays or arrays[key].shape != shape:
            raise RuntimeError(
                f"regression chunk {candidate_path} has invalid {key}"
            )
    if not np.array_equal(
        arrays["dataset_index"],
        np.arange(start, stop, dtype=np.int32),
    ):
        raise RuntimeError(f"regression coverage changed: {candidate_path}")
    if not np.all(arrays["exact_match"] == 1):
        raise RuntimeError(f"regression mismatch recorded: {candidate_path}")
    return arrays

def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()

def semantic_from_extracted(extracted: dict[str, Any]) -> dict[str, Any]:
    return {
        "margin": {
            "value": float(extracted["margin"]),
            "hex": float(extracted["margin"]).hex(),
        },
        "attacker_count": int(extracted["count"]),
        "route_ids": [int(item) for item in extracted["route_ids"]],
        "source_mask": int(
            sum(
                int(bit) << index
                for index, bit in enumerate(extracted["source"])
            )
        ),
        "transit_mask": int(
            sum(
                int(bit) << index
                for index, bit in enumerate(extracted["transit"])
            )
        ),
        "victim_mask": int(
            sum(
                int(bit) << index
                for index, bit in enumerate(extracted["victim"])
            )
        ),
        "path_mask": int(
            sum(
                int(bit) << index
                for index, bit in enumerate(extracted["path"])
            )
        ),
    }

